# -*- coding: utf-8 -*-
"""Lota 15, tíundi tími: prósentur, ný heild og breytiþáttur.
Hljóðlaust GGJ-myndband. Manim Community 0.19.
Innbyggt Latin Modern-letur og óbreytt leyfi; engin fonts-mappa þarf.
Keyrsla: manim -pqm lota15_timi10_prosentur.py ProsenturOgNyHeild
Gæði eru valin við keyrslu. LaTeX og dvisvgm þurfa að vera tiltæk.
"""

from html import escape as html_escape
from math import atan2
from unicodedata import normalize as unicode_normalize
from pathlib import Path as FilePath
import re
from base64 import b64decode as _ggj_b64decode
from io import BytesIO as _ggj_BytesIO
from tempfile import TemporaryDirectory as _ggj_TemporaryDirectory
from zipfile import ZipFile as _ggj_ZipFile

import manimpango
import numpy as np
from manim import *


__author__ = "GGJ"
LETUR = "Latin Modern Roman"
BAKGRUNNUR = "#FCF8F2"
BLEK = "#2E2C29"
GRATT = "#747678"
GRAENT = "#4F7353"
APPELSINUGULT = "#E97728"
BLATT = "#728299"
THRIHYRNINGUR = "#D9C5AF"
UTLINA = "#7A858F"
PAUSU_STUDULL = 1.0  # 1.2 gefur 20% lengri lestrarpásur.


# Heldur tímabundnum leturskrám lifandi meðan Manim notar þær.
_GGJ_FONT_DIR = None
_GGJ_FONT_READY = False


def setja_upp_letur():
    """Hlaða innbyggðu Latin Modern-letri fyrir þetta Manim-ferli.

    Engin niðurhalstenging, kerfisuppsetning eða ytri fonts-mappa þarf.
    Skrárnar eru óbreytt upprunaleg OTF-letur með meðfylgjandi leyfum.
    Native skráning styður Windows; fontconfig er varaleið þar sem
    Pango er byggt með þeim bakenda. Ekki er skipt í annað letur.
    """
    global LETUR, _GGJ_FONT_DIR, _GGJ_FONT_READY
    if _GGJ_FONT_READY:
        return
    if _GGJ_FONT_DIR is None:
        # Windows getur haldið skráðu OTF-letri læstu þar til ferlinu lýkur.
        # Best-effort hreinsun má þá ekki valda PermissionError við lokun.
        _GGJ_FONT_DIR = _ggj_TemporaryDirectory(
            prefix="ggj-manim-fonts-", ignore_cleanup_errors=True,
        )
        mappa = FilePath(_GGJ_FONT_DIR.name)
        # Lesa aðeins þessi föstu nöfn úr eigin innbyggða pakka.
        with _ggj_ZipFile(_ggj_BytesIO(_ggj_b64decode(_GGJ_FONT_ARCHIVE))) as pakki:
            for nafn in (
                "lmroman10-regular.otf", "lmroman10-bold.otf",
                "GUST-FONT-LICENSE.TXT", "LPPL-1.3c.txt",
                "README-Latin-Modern.TXT",
            ):
                (mappa / nafn).write_bytes(pakki.read(nafn))
    mappa = FilePath(_GGJ_FONT_DIR.name)
    villur = []
    # Nota fyrst studda kerfisleið ManimPango. Eldri uppsetningar geta
    # notað fontconfig; sú leið er aðeins reynd ef sú fyrri dugar ekki.
    for adferd in ("register_font", "fc_register_font"):
        skra_letur = getattr(manimpango, adferd, None)
        if skra_letur is None:
            continue
        for nafn in ("lmroman10-regular.otf", "lmroman10-bold.otf"):
            try:
                if skra_letur(str(mappa / nafn)) is False:
                    villur.append(adferd + ": " + nafn + " returned False")
            except (OSError, RuntimeError, AssertionError, AttributeError) as villa:
                villur.append(adferd + ": " + str(villa))
        # Sum útgáfunúmer geyma leturlista í skyndiminni.
        for fn in (manimpango.list_fonts, getattr(Text, "font_list", None)):
            hreinsa = getattr(fn, "cache_clear", None)
            if hreinsa is not None:
                hreinsa()
        heiti = {f.casefold(): f for f in manimpango.list_fonts()}
        # Windows/Pango birtir þetta letur einnig sem "Latin Modern Roman 10".
        for kandidat in ("Latin Modern Roman", "Latin Modern Roman 10", "LM Roman 10"):
            if kandidat.casefold() in heiti:
                LETUR = heiti[kandidat.casefold()]
                _GGJ_FONT_READY = True
                return
    # ASCII-villuboð haldast læsileg í Windows-úttaki Sideview.
    skyld = [f for f in heiti.values()
             if "latin modern" in f.casefold() or "lm roman" in f.casefold()]
    raise RuntimeError(
        "GGJ: Embedded Latin Modern font registration failed. "
        "ManimPango=" + str(getattr(manimpango, "__version__", "unknown"))
        + "; matching font names=" + repr(skyld)
        + "; details=" + repr(villur)
    )


def texti(efni, staerd=30, litur=BLEK, aherslur=(), feit=False):
    """Íslenskir stafir haldast saman við litun áhersluorða."""
    efni = unicode_normalize("NFC", efni)
    ordalisti = sorted(
        {unicode_normalize("NFC", ord_) for ord_ in aherslur if ord_},
        key=len, reverse=True,
    )
    if ordalisti:
        mynstur = "(" + "|".join(re.escape(o) for o in ordalisti) + ")"
        hlutar = re.split(mynstur, efni)
        markup = "".join(
            f'<span foreground="{APPELSINUGULT}">{html_escape(h)}</span>'
            if h in ordalisti else html_escape(h)
            for h in hlutar
        )
    else:
        markup = html_escape(efni)
    return MarkupText(markup, font=LETUR, font_size=staerd, color=litur,
                      weight=BOLD if feit else NORMAL)


def mathi(latex, staerd=36, litur=BLEK):
    """LaTeX sér áfram um veldi, brot og rótartákn; letrið er ritvélarletur."""
    return MathTex(r"\mathtt{" + latex + "}", font_size=staerd, color=litur)


def mathlina(*hlutar, staerd=54):
    # Bilin tilheyra hverjum lið svo litun og TransformFromCopy haldi
    # réttri skiptingu í MathTex, líka í Manim 0.19.
    brot = [r"\mathtt{" + h + "}" + (r"\;" if i < len(hlutar) - 1 else "")
            for i, h in enumerate(hlutar)]
    return MathTex(*brot, font_size=staerd, color=BLEK)






class ProsenturOgNyHeild(Scene):
    """Dæmi 64: prósentuhluti, ný heild og breytiþáttur."""

    def lesa(self, sek=4):
        self.wait(sek * PAUSU_STUDULL)

    def skyring(self, efni, aherslur=()):
        ny = texti(efni, 28, aherslur=aherslur)
        if ny.width > 12.5:
            ny.scale_to_fit_width(12.5)
        ny.move_to([0, -3.2, 0])
        if self.skyringartexti is None:
            self.play(FadeIn(ny, shift=UP*0.06), run_time=0.65)
        else:
            self.play(FadeOut(self.skyringartexti), FadeIn(ny), run_time=0.65)
        self.skyringartexti = ny

    def merka(self, nafn):
        self.lykilrammar[nafn] = self.time

    @staticmethod
    def stika(vinstri, breidd, litur, opacity=0.28, stroke=0):
        return Rectangle(width=breidd, height=0.85, stroke_color=litur,
                         stroke_width=stroke, fill_color=litur, fill_opacity=opacity
                         ).move_to([vinstri+breidd/2, 0.65, 0])

    @staticmethod
    def fyrirsogn(prosenta, ord, breyta=None):
        hlutar = [mathi(prosenta+r"\%", 36, APPELSINUGULT), texti(ord, 29, feit=True)]
        if breyta:
            hlutar.append(mathi(breyta+r"=1\,000\ \mathrm{kr.}", 34, GRAENT))
        return VGroup(*hlutar).arrange(RIGHT, buff=0.32).move_to([0, 2.24, 0])

    def construct(self):
        setja_upp_letur()
        self.camera.background_color = BAKGRUNNUR
        self.skyringartexti = None
        self.lykilrammar = {}
        merki = texti("GGJ", 18, GRATT).set_opacity(0.55).to_corner(DR, buff=0.22)
        merki.set_z_index(100)
        self.add(merki)
        titill = texti("Prósentur og ný heild", 43, feit=True, aherslur=("ný heild",))
        titill.move_to([0, 3.3, 0])
        self.play(FadeIn(titill, shift=DOWN*0.1), run_time=1.1)

        # Sameiginlegur mælikvarði: 100% = 8 lengdareiningar á skjánum.
        x0, grunnbreidd = -4.6, 8.0
        vidbot = grunnbreidd * 0.15
        afslattur = grunnbreidd * 0.08
        eftir = grunnbreidd * 0.92
        assert abs(vidbot/grunnbreidd-0.15) < 1e-12
        assert abs(afslattur+eftir-grunnbreidd) < 1e-12

        # Upphafsgildið er alltaf viðmið prósentanna í þessum dæmum.
        skilgr_x = VGroup(mathi("x", 38, GRAENT),
                         texti("er upphaflega upphæðin.", 29)).arrange(RIGHT, buff=0.16)
        skilgr_x.move_to([0, 2.24, 0])
        grunnur = self.stika(x0, grunnbreidd, GRAENT)
        grunnrammi = self.stika(x0, grunnbreidd, BLEK, opacity=0, stroke=2.3)
        hundrad = mathi(r"100\%", 35, GRAENT).move_to([x0+grunnbreidd/2, 1.48, 0])
        xmerki = mathi("x", 47, GRAENT).move_to(grunnur)
        self.play(FadeIn(skilgr_x), FadeIn(grunnur), Create(grunnrammi), Write(hundrad),
                  Write(xmerki), run_time=1.6)
        self.skyring("Upphaflega upphæðin samsvarar hundrað prósentum.", ("Upphaflega upphæðin",))
        self.lesa(5)
        self.merka("upphafsgildi")

        # Fimmtán prósent bætast við heila grunnstikuna, í réttum lengdarhlutföllum.
        haekkun = self.fyrirsogn("15", "hækkun")
        auki = self.stika(x0+grunnbreidd, vidbot, APPELSINUGULT, opacity=0.35, stroke=2.1)
        fimmtan = mathi(r"15\%", 33, APPELSINUGULT).move_to([4.0, 1.48, 0])
        hlutinn = mathi("0{,}15x", 37, APPELSINUGULT).move_to([4.0, -0.29, 0])
        visir = Line([4.0, 0.225, 0], [4.0, 0.04, 0], color=APPELSINUGULT, stroke_width=1.4)
        hundradshlutar = mathlina(r"15\%", "=", r"\frac{15}{100}", "=", "0{,}15", staerd=44)
        hundradshlutar.move_to([0, -1.23, 0])
        hundradshlutar[0].set_color(APPELSINUGULT); hundradshlutar[4].set_color(APPELSINUGULT)
        self.play(ReplacementTransform(skilgr_x, haekkun), GrowFromEdge(auki, LEFT),
                  Write(fimmtan), run_time=1.5)
        self.skyring("Prósent merkir hundraðshluta.", ("hundraðshluta",))
        self.play(Write(hundradshlutar), run_time=1.4)
        self.lesa(4)
        self.play(Create(visir), Write(hlutinn), run_time=0.9)
        self.skyring("Hækkunin bætist við alla upphaflegu upphæðina.", ("bætist við",))
        self.lesa(4)
        self.merka("haekkunarhluti")

        prosenta = mathlina(r"100\%", "+", r"15\%", "=", r"115\%", staerd=48)
        prosenta.move_to([0, -1.18, 0]); prosenta[0].set_color(GRAENT)
        prosenta[2].set_color(APPELSINUGULT)
        regla = mathlina("x", "+", "0{,}15x", "=", "1{,}15", "x", staerd=54)
        regla.move_to([0, -2.22, 0]); regla[0].set_color(GRAENT)
        regla[2].set_color(APPELSINUGULT); regla[4].set_color(APPELSINUGULT); regla[5].set_color(GRAENT)
        self.play(ReplacementTransform(hundradshlutar, prosenta), run_time=1.3)
        self.lesa(3)
        self.play(Write(regla), run_time=1.5)
        ahersla = SurroundingRectangle(regla[4], color=APPELSINUGULT, buff=0.11,
                                       stroke_width=1.7, corner_radius=0.04)
        self.skyring("Notum breytiþáttinn til að finna nýju upphæðina.", ("breytiþáttinn",))
        self.play(Create(ahersla), run_time=0.7)
        self.lesa(5)
        self.merka("breytithattur_115")

        # Töludæmi skilur hækkunina (150 kr.) frá nýju heildinni (1150 kr.).
        haekkun_t = self.fyrirsogn("15", "hækkun", "x")
        grunn_t = mathi(r"1\,000\ \mathrm{kr.}", 40, GRAENT).move_to(xmerki)
        auki_t = mathi(r"150\ \mathrm{kr.}", 33, APPELSINUGULT).move_to(hlutinn)
        svar_t = mathlina("1{,}15", r"\cdot1\,000", "=", r"1\,150\ \mathrm{kr.}", staerd=54)
        svar_t.move_to(regla); svar_t[0].set_color(APPELSINUGULT); svar_t[3].set_color(GRAENT)
        self.skyring("Leggjum hækkunina við upphaflega upphæðina.", ("hækkunina",))
        self.play(ReplacementTransform(haekkun, haekkun_t), ReplacementTransform(xmerki, grunn_t),
                  ReplacementTransform(hlutinn, auki_t), ReplacementTransform(regla, svar_t),
                  FadeOut(ahersla), run_time=1.6)
        self.lesa(6)
        self.merka("haekkun_i_kronum")
        self.play(FadeOut(VGroup(haekkun_t, grunnur, grunnrammi, hundrad, grunn_t,
                                auki, fimmtan, auki_t, visir, prosenta, svar_t)), run_time=0.9)

        # Sama 100% grunnlengd. Afsláttur fjarlægir 8% og skilur 92% eftir.
        skilgr_y = VGroup(mathi("y", 38, GRAENT),
                         texti("er upphaflega upphæðin.", 29)).arrange(RIGHT, buff=0.16)
        skilgr_y.move_to([0, 2.24, 0])
        megin = self.stika(x0, eftir, GRAENT)
        brott = self.stika(x0+eftir, afslattur, GRAENT)
        rammi = self.stika(x0, grunnbreidd, BLEK, opacity=0, stroke=2.3)
        heildarprosent = mathi(r"100\%", 35, GRAENT).move_to([x0+grunnbreidd/2, 1.48, 0])
        ymerki = mathi("y", 47, GRAENT).move_to([x0+grunnbreidd/2, 0.65, 0])
        self.play(FadeIn(skilgr_y), FadeIn(megin), FadeIn(brott), Create(rammi),
                  Write(heildarprosent), Write(ymerki), run_time=1.5)
        self.skyring("Afsláttur er reiknaður af upphaflegu upphæðinni.", ("upphaflegu upphæðinni",))
        self.lesa(4)
        fyr_afsl = self.fyrirsogn("8", "afsláttur")
        atta = mathi(r"8\%", 32, APPELSINUGULT).move_to([3.08, 1.48, 0])
        hlutafsl = mathi("0{,}08y", 37, APPELSINUGULT).move_to([4.05, -0.29, 0])
        visir2 = Line([3.08, 0.225, 0], [4.05, 0.04, 0], color=APPELSINUGULT, stroke_width=1.4)
        hlutfall = mathlina(r"8\%", "=", r"\frac{8}{100}", "=", "0{,}08", staerd=44)
        hlutfall.move_to([0, -1.23, 0]); hlutfall[0].set_color(APPELSINUGULT)
        hlutfall[4].set_color(APPELSINUGULT)
        self.play(ReplacementTransform(skilgr_y, fyr_afsl),
                  brott.animate.set_fill(APPELSINUGULT, opacity=0.35), Write(atta), run_time=1.3)
        self.play(Write(hlutfall), Create(visir2), Write(hlutafsl), run_time=1.5)
        self.lesa(4)
        self.merka("afslattarhluti")

        prosent_eftir = mathlina(r"100\%", "-", r"8\%", "=", r"92\%", staerd=48)
        prosent_eftir.move_to([0, -1.18, 0]); prosent_eftir[0].set_color(GRAENT)
        prosent_eftir[2].set_color(APPELSINUGULT); prosent_eftir[4].set_color(GRAENT)
        label92 = mathi(r"92\%", 35, GRAENT).move_to([x0+eftir/2, 1.48, 0])
        verd_eftir = mathi("0{,}92y", 43, GRAENT).move_to(megin)
        afslregla = mathlina("y", "-", "0{,}08y", "=", "0{,}92", "y", staerd=54)
        afslregla.move_to([0, -2.22, 0]); afslregla[0].set_color(GRAENT)
        afslregla[2].set_color(APPELSINUGULT); afslregla[4].set_color(APPELSINUGULT)
        afslregla[5].set_color(GRAENT)
        self.skyring("Tökum afsláttinn frá. Restin er nýja upphæðin.", ("Restin",))
        self.play(FadeOut(brott, shift=DOWN*0.45),
                  ReplacementTransform(heildarprosent, label92), ReplacementTransform(ymerki, verd_eftir),
                  ReplacementTransform(hlutfall, prosent_eftir), run_time=1.6)
        self.lesa(3)
        self.play(Write(afslregla), run_time=1.5)
        ahersla2 = SurroundingRectangle(afslregla[4], color=APPELSINUGULT, buff=0.11,
                                        stroke_width=1.7, corner_radius=0.04)
        self.skyring("Breytiþátturinn lýsir því sem stendur eftir af heildinni.", ("stendur eftir",))
        self.play(Create(ahersla2), run_time=0.7)
        self.lesa(5)
        self.merka("breytithattur_092")

        afsl_t = self.fyrirsogn("8", "afsláttur", "y")
        eftir_t = mathi(r"920\ \mathrm{kr.}", 40, GRAENT).move_to(verd_eftir)
        brott_t = mathi(r"80\ \mathrm{kr.}", 33, APPELSINUGULT).move_to(hlutafsl)
        svar2 = mathlina("0{,}92", r"\cdot1\,000", "=", r"920\ \mathrm{kr.}", staerd=54)
        svar2.move_to(afslregla); svar2[0].set_color(APPELSINUGULT); svar2[3].set_color(GRAENT)
        self.skyring("Eftir afslátt greiðum við upphæðina sem stendur eftir.", ("stendur eftir",))
        self.play(ReplacementTransform(fyr_afsl, afsl_t), ReplacementTransform(verd_eftir, eftir_t),
                  ReplacementTransform(hlutafsl, brott_t), ReplacementTransform(afslregla, svar2),
                  FadeOut(ahersla2), run_time=1.6)
        self.lesa(6)
        self.merka("afslattur_i_kronum")
        self.play(FadeOut(VGroup(afsl_t, megin, rammi, label92, eftir_t, atta,
                                brott_t, visir2, prosent_eftir, svar2)), run_time=0.9)

        # Báðir breytiþættir bornir saman; hundraðshlutar verða tugabrot.
        vheiti = texti("Hækkun", 30, feit=True).move_to([-3.3, 2.18, 0])
        hheiti = texti("Afsláttur", 30, feit=True).move_to([3.3, 2.18, 0])
        vpros = mathi(r"100\%+15\%=115\%", 43).move_to([-3.3, 1.0, 0])
        hpros = mathi(r"100\%-8\%=92\%", 43).move_to([3.3, 1.0, 0])
        vthattur = mathlina(r"115\%", "=", "1{,}15", staerd=54).move_to([-3.3, -0.35, 0])
        hthattur = mathlina(r"92\%", "=", "0{,}92", staerd=54).move_to([3.3, -0.35, 0])
        vthattur[2].set_color(APPELSINUGULT); hthattur[2].set_color(APPELSINUGULT)
        vord = texti("Breytiþáttur", 26, GRATT).move_to([-3.3, -1.3, 0])
        hord = texti("Breytiþáttur", 26, GRATT).move_to([3.3, -1.3, 0])
        skil = Line([0, 2.2, 0], [0, -1.65, 0], color=UTLINA, stroke_width=1.1).set_opacity(0.35)
        loka = texti("Finndu fyrst hvað nýja heildin er mörg prósent.", 30,
                     aherslur=("nýja heildin",)).move_to([0, -2.28, 0])
        self.play(FadeIn(vheiti), FadeIn(hheiti), Create(skil), Write(vpros), Write(hpros),
                  Write(vthattur), Write(hthattur), FadeIn(vord), FadeIn(hord), FadeIn(loka), run_time=2)
        self.skyring("Margfaldaðu upphaflegu upphæðina með breytiþættinum.", ("breytiþættinum",))
        self.lesa(8)
        self.merka("nidurstada")

        import os as _os
        import json as _json
        if _os.environ.get("GGJ_QA_TIMELINE"):
            FilePath(_os.environ["GGJ_QA_TIMELINE"]).write_text(
                _json.dumps(self.lykilrammar, ensure_ascii=False, indent=2), encoding="utf-8")


